                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                for rr, cc, sr, sc in ((r - dr, c - dc, -dr, -dc),
                                        (r2 + dr, c2 + dc, dr, dc)):
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != bg and grid[rr][cc] != color:
                            break
